sys_variable_value.value:
// Diagnostic: report the real payment/invoice state so a failure here localises the cause.
function num(v) { return parseFloat(v) || 0; }
// steps(SYS_ID) is ATF's injected accessor for an earlier step's outputs. GEM {{ step[...] }}
// templates are NOT substituted in a script body, so the sys_id must be passed literally.
var invoiceId = steps("8639018182c540ea9f6f4c326fb8694c").record_id;
if (!invoiceId || ('' + invoiceId).length !== 32) {
    throw new Error('unresolved step reference for invoiceId: ' + invoiceId);
}
var inv = new GlideRecord('x_2298436_snackf_0_invoice');
if (!inv.get(invoiceId)) throw new Error('invoice not found: ' + invoiceId);

var rows = [], summed = 0;
var p = new GlideRecord('x_2298436_snackf_0_payment');
p.addQuery('invoice', invoiceId);
p.orderBy('sys_created_on');
p.query();
while (p.next()) {
    rows.push(p.getValue('number') + '=' + p.getValue('payment_amount'));
    summed += num(p.getValue('payment_amount'));
}
summed = Math.round(summed * 100) / 100;

stepResult.setOutputMessage(
    'payment_rows=' + rows.length + ' [' + rows.join(', ') + ']' +
    ' summed=' + summed +
    ' | invoice total=' + inv.getValue('total_invoice_amount') +
    ' taxable=' + inv.getValue('taxable_amount') +
    ' cgst=' + inv.getValue('cgst_amount') + ' sgst=' + inv.getValue('sgst_amount') +
    ' igst=' + inv.getValue('igst_amount') +
    ' amount_paid=' + inv.getValue('amount_paid') +
    ' balance_due=' + inv.getValue('balance_due') +
    ' status=' + inv.getValue('invoice_status')
);

// Structural facts: both payments must exist and their sum must equal the stored rollup.
assertEqual({ name: 'two payment rows exist against the invoice', shouldbe: 2, value: rows.length });
assertEqual({ name: 'stored amount_paid equals an independent re-sum', shouldbe: summed, value: num(inv.getValue('amount_paid')) });
